INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('986ec036-538c-4d29-9ce3-d78185c46588', 'c1c2c3d4-3030-4000-8000-000000000030', 2, 'Pausar', 'Semana 1 — Despertar', '{"pch": "Nem todo movimento \u00e9 progresso\u2026 \u00e0s vezes \u00e9 fuga.", "verse": "Sl 46,10", "lectio": "Sente-se em sil\u00eancio por 3 minutos antes de ler. Depois leia o salmo duas vezes.", "practice": "Identifique uma a\u00e7\u00e3o que voc\u00ea repete por ansiedade, n\u00e3o por necessidade.", "question": "Do que voc\u00ea est\u00e1 fugindo?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;